=== src/main/java/hotel/reservations/ReservationStore.java
     1	package hotel.reservations;
     2	
     3	import java.math.BigDecimal;
     4	import java.sql.Connection;
     5	import java.sql.Date;
     6	import java.sql.PreparedStatement;
     7	import java.sql.ResultSet;
     8	import java.sql.SQLException;
     9	import java.time.LocalDate;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	import java.util.Optional;
    13	import javax.sql.DataSource;
    14	
    15	/** Keeps the reservations in the database. */
    16	public final class ReservationStore {
    17	
    18	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    19	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund, "
    20	            + "company_cnpj, company_name, guest_passport, guest_country";
    21	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
    22	    private static final String EXCLUSION_VIOLATION = "23P01";
    23	
    24	    private final DataSource dataSource;
    25	
    26	    public ReservationStore(DataSource dataSource) {
    27	        this.dataSource = dataSource;
    28	    }
    29	
    30	    /** Saves a new reservation; the database numbers it. */
    31	    Reservation add(NewReservation request, Price price) {
    32	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
    33	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, company_cnpj, company_name, guest_passport, guest_country) "
    34	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
    35	        try (Connection connection = dataSource.getConnection();
    36	                PreparedStatement statement = connection.prepareStatement(insert)) {
    37	            statement.setInt(1, request.roomNumber());
    38	            statement.setString(2, request.guest().name());
    39	            statement.setString(3, request.guest().email());
    40	            statement.setString(4, request.guest().cpf());
    41	            statement.setDate(5, Date.valueOf(request.checkIn()));
    42	            statement.setDate(6, Date.valueOf(request.checkOut()));
    43	            statement.setInt(7, request.guests());
    44	            statement.setString(8, request.ratePlan().name());
    45	            statement.setInt(9, price.nights());
    46	            statement.setBigDecimal(10, price.subtotal());
    47	            statement.setBigDecimal(11, price.discount());
    48	            statement.setBigDecimal(12, price.total());
    49	            statement.setString(13, ReservationStatus.PENDING.name());
    50	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
    51	            statement.setString(15, request.guest().companyCnpj());
    52	            statement.setString(16, request.guest().companyName());
    53	            statement.setString(17, request.guest().passport());
    54	            statement.setString(18, request.guest().country());
    55	            try (ResultSet generated = statement.executeQuery()) {
    56	                generated.next();
    57	                return new Reservation(generated.getLong("id"), request, price);
    58	            }
    59	        } catch (SQLException failure) {
    60	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
    61	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
    62	                        "room " + request.roomNumber() + " is taken on some of those nights");
    63	            }
    64	            throw new IllegalStateException("could not save the reservation", failure);
    65	        }
    66	    }
    67	
    68	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
    69	    void update(Reservation reservation) {
    70	        try (Connection connection = dataSource.getConnection();
    71	                PreparedStatement statement = connection.prepareStatement(
    72	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    73	            statement.setString(1, reservation.status().name());
    74	            statement.setBigDecimal(2, reservation.amountPaid());
    75	            statement.setBigDecimal(3, reservation.refund());
    76	            statement.setLong(4, reservation.id());
    77	            statement.executeUpdate();
    78	        } catch (SQLException failure) {
    79	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
    80	        }
    81	    }
    82	
    83	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
    84	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    85	        try (Connection connection = dataSource.getConnection();
    86	                PreparedStatement select = connection.prepareStatement(
    87	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    88	                                + "AND check_in < ? AND ? < check_out")) {
    89	            select.setInt(1, roomNumber);
    90	            select.setDate(2, Date.valueOf(checkOut));
    91	            select.setDate(3, Date.valueOf(checkIn));
    92	            try (ResultSet rows = select.executeQuery()) {
    93	                return rows.next();
    94	            }
    95	        } catch (SQLException failure) {
    96	            throw new IllegalStateException("could not check room " + roomNumber, failure);
    97	        }
    98	    }
    99	
   100	    public Optional<Reservation> find(long id) {
   101	        try (Connection connection = dataSource.getConnection();
   102	                PreparedStatement select = connection.prepareStatement(
   103	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
   104	            select.setLong(1, id);
   105	            try (ResultSet rows = select.executeQuery()) {
   106	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
   107	            }
   108	        } catch (SQLException failure) {
   109	            throw new IllegalStateException("could not read reservation " + id, failure);
   110	        }
   111	    }
   112	
   113	    public List<Reservation> all() {
   114	        try (Connection connection = dataSource.getConnection();
   115	                PreparedStatement select = connection.prepareStatement(
   116	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
   117	                ResultSet rows = select.executeQuery()) {
   118	            List<Reservation> reservations = new ArrayList<>();
   119	            while (rows.next()) {
   120	                reservations.add(read(rows));
   121	            }
   122	            return reservations;
   123	        } catch (SQLException failure) {
   124	            throw new IllegalStateException("could not read the reservations", failure);
   125	        }
   126	    }
   127	
   128	    private static Reservation read(ResultSet row) throws SQLException {
