    14	
    15	/** Keeps the reservations in the database. */
    16	public final class ReservationStore {
    17	
    18	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    19	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund, "
    20	            + "company_cnpj, company_name, guest_passport, guest_country";
    21	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
    22	    private static final String EXCLUSION_VIOLATION = "23P01";
    23	
    24	    private final DataSource dataSource;
    25	
    26	    public ReservationStore(DataSource dataSource) {
    27	        this.dataSource = dataSource;
    28	    }
    29	
    30	    /** Saves a new reservation; the database numbers it. */
    31	    Reservation add(NewReservation request, Price price) {
    32	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
    33	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, company_cnpj, company_name, guest_passport, guest_country) "
    34	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
    35	        try (Connection connection = dataSource.getConnection();
    36	                PreparedStatement statement = connection.prepareStatement(insert)) {
    37	            statement.setInt(1, request.roomNumber());
    38	            statement.setString(2, request.guest().name());
    39	            statement.setString(3, request.guest().email());
    40	            statement.setString(4, request.guest().cpf());
    41	            statement.setDate(5, Date.valueOf(request.checkIn()));
    42	            statement.setDate(6, Date.valueOf(request.checkOut()));
    43	            statement.setInt(7, request.guests());
    44	            statement.setString(8, request.ratePlan().name());
    45	            statement.setInt(9, price.nights());
    46	            statement.setBigDecimal(10, price.subtotal());
    47	            statement.setBigDecimal(11, price.discount());
    48	            statement.setBigDecimal(12, price.total());
    49	            statement.setString(13, ReservationStatus.PENDING.name());
    50	            statement.setBigDecimal(14, PriceCalculator.cents(BigDecimal.ZERO));
    51	            statement.setString(15, request.guest().companyCnpj());
    52	            statement.setString(16, request.guest().companyName());
    53	            statement.setString(17, request.guest().passport());
    54	            statement.setString(18, request.guest().country());
    55	            try (ResultSet generated = statement.executeQuery()) {
    56	                generated.next();
