117	                HttpResponse.BodyHandlers.ofString());
118	    }
119	
120	    private HttpResponse<String> post(String path, String body) throws IOException, InterruptedException {
121	        return client.send(HttpRequest.newBuilder(URI.create(baseUrl + path))
122	                        .header("Content-Type", "application/json")
123	                        .POST(HttpRequest.BodyPublishers.ofString(body))
124	                        .build(),
125	                HttpResponse.BodyHandlers.ofString());
126	    }
