128	    @Test
129	    void listsTheRooms() throws Exception {
130	        HttpResponse<String> response = get("/rooms");
131	
132	        assertEquals(200, response.statusCode());
133	        JsonNode rooms = json.readTree(response.body());
134	        assertEquals(5, rooms.size());
135	        assertEquals(101, rooms.get(0).get("number").asInt());
136	        assertEquals("249.9", rooms.get(0).get("nightlyRate").asText());
137	    }
138	
139	    @Test
140	    void booksConfirmsAndChecksOut() throws Exception {
141	        HttpResponse<String> created = post("/reservations", RESERVATION_JSON);
142	        assertEquals(201, created.statusCode());
143	        JsonNode reservation = json.readTree(created.body());
144	        long id = reservation.get("id").asLong();
145	        assertEquals("PENDING", reservation.get("status").asText());
146	        assertEquals("2027-07-10", reservation.get("checkIn").asText());
147	        assertEquals(935.76, reservation.get("total").asDouble());
148	
149	        assertEquals(200, post("/reservations/" + id + "/confirmation", "").statusCode());
150	        JsonNode messages = json.readTree(get("/messages").body());
151	        assertEquals(1, messages.size());
152	        assertEquals("carla@example.com", messages.get(0).get("to").asText());
153	
154	        assertEquals(200, post("/reservations/" + id + "/check-in", "").statusCode());
155	        HttpResponse<String> checkedOut = post("/reservations/" + id + "/check-out", "");
156	        assertEquals(200, checkedOut.statusCode());
157	        assertEquals("Comprovante de reserva", json.readTree(checkedOut.body()).get("title").asText());
158	        assertEquals("CHECKED_OUT", json.readTree(get("/reservations/" + id).body()).get("status").asText());
159	    }
160	
161	    @Test
162	    void answersErrorsWithACode() throws Exception {
163	        HttpResponse<String> missingFields = post("/reservations", "{\"roomNumber\": 201}");
164	        assertEquals(400, missingFields.statusCode());
165	        assertEquals("INVALID_REQUEST", json.readTree(missingFields.body()).get("error").asText());
166	
167	        assertEquals(400, post("/reservations", "not json").statusCode());
168	        assertEquals(400, post("/reservations", RESERVATION_JSON.replace("STANDARD", "VIP")).statusCode());
169	        assertEquals(404, get("/reservations/42").statusCode());
170	        assertEquals(404, get("/reservations/abc").statusCode());
171	
172	        post("/reservations", RESERVATION_JSON);
173	        HttpResponse<String> taken = post("/reservations", RESERVATION_JSON);
174	        assertEquals(409, taken.statusCode());
175	        assertEquals("ROOM_UNAVAILABLE", json.readTree(taken.body()).get("error").asText());
176	    }
177	
178	    @Test
179	    void servesTheReportsAsCsv() throws Exception {
180	        long id = json.readTree(post("/reservations", RESERVATION_JSON).body()).get("id").asLong();
181	        post("/reservations/" + id + "/confirmation", "");
182	
183	        HttpResponse<String> occupancy = get("/reports/occupancy?date=2027-07-11");
184	        assertEquals(200, occupancy.statusCode());
185	        assertTrue(occupancy.headers().firstValue("Content-Type").orElse("").startsWith("text/csv"));
186	        assertTrue(occupancy.body().endsWith("total,1/5\n"));
187	
188	        assertTrue(get("/reports/revenue?month=2027-07").body().endsWith("total,935.76\n"));
189	        assertEquals(400, get("/reports/revenue?month=july").statusCode());
190	        assertEquals(400, get("/reports/occupancy").statusCode());
191	    }
192	}
