193	package hotel;
194	
195	import java.sql.Connection;
196	import java.sql.SQLException;
197	import java.sql.Statement;
198	import javax.sql.DataSource;
199	
200	/**
201	 * The database the tests use, in the same variables as the service (DB_URL, DB_USER, DB_PASSWORD), emptied when
202	 * opened: no reservation, no message, and the numbering back to 1. The rooms stay.
203	 */
204	public final class EmptyDatabase implements AutoCloseable {
205	
206	    private final Database database = new Database(System.getenv());
207	
208	    public EmptyDatabase() {
209	        try (Connection connection = database.dataSource().getConnection();
210	                Statement statement = connection.createStatement()) {
211	            statement.execute("TRUNCATE reservations, messages RESTART IDENTITY CASCADE");
212	        } catch (SQLException failure) {
213	            throw new IllegalStateException("could not empty the test database", failure);
214	        }
215	    }
216	
217	    public DataSource dataSource() {
218	        return database.dataSource();
219	    }
220	
221	    @Override
222	    public void close() {
223	        database.close();
224	    }
225	}

